import json
import threading
import unittest
import urllib.error
from http.server import BaseHTTPRequestHandler, HTTPServer
from unittest import mock

import openai_client


class RecordingHandler(BaseHTTPRequestHandler):
    last_request = {}

    def do_POST(self):
        length = int(self.headers.get("Content-Length", 0))
        body = self.rfile.read(length)
        RecordingHandler.last_request = {
            "path": self.path,
            "auth": self.headers.get("Authorization"),
            "content_type": self.headers.get("Content-Type"),
            "body": json.loads(body),
        }
        if self.headers.get("Authorization") != "Bearer dummy-key":
            self.send_response(401)
            self.end_headers()
            self.wfile.write(b'{"error": "unauthorized"}')
            return
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.end_headers()
        self.wfile.write(json.dumps({"id": "resp_123", "status": "completed"}).encode())

    def log_message(self, *args):
        pass


class TestClient(unittest.TestCase):
    server = None
    port = None

    @classmethod
    def setUpClass(cls):
        cls.server = HTTPServer(("127.0.0.1", 0), RecordingHandler)
        cls.port = cls.server.server_address[1]
        threading.Thread(target=cls.server.serve_forever, daemon=True).start()

    @classmethod
    def tearDownClass(cls):
        cls.server.shutdown()

    def test_post_and_headers_and_body(self):
        result = openai_client.send_request(
            "Hello", "gpt-4o", api_key="dummy-key", base_url="http://127.0.0.1:%d/v1" % self.port
        )
        self.assertEqual(result, {"id": "resp_123", "status": "completed"})
        req = RecordingHandler.last_request
        self.assertEqual(req["path"], "/v1/responses")
        self.assertEqual(req["auth"], "Bearer dummy-key")
        self.assertEqual(req["content_type"], "application/json")
        self.assertEqual(req["body"], {"model": "gpt-4o", "input": "Hello"})

    def test_trailing_slash(self):
        openai_client.send_request(
            "Hi", "gpt-4o", api_key="dummy-key", base_url="http://127.0.0.1:%d/v1/" % self.port
        )
        self.assertEqual(RecordingHandler.last_request["path"], "/v1/responses")

    def test_env_key(self):
        with mock.patch.dict("os.environ", {"OPENAI_API_KEY": "dummy-key"}):
            result = openai_client.send_request("Hi", "gpt-4o", base_url="http://127.0.0.1:%d/v1" % self.port)
        self.assertEqual(result["status"], "completed")

    def test_missing_key_raises_valueerror(self):
        env = {"OPENAI_API_KEY": ""} if "OPENAI_API_KEY" not in __import__("os").environ else {}
        with mock.patch.dict("os.environ", env, clear=False):
            if "OPENAI_API_KEY" in __import__("os").environ:
                self.skipTest("OPENAI_API_KEY set in real environment")
        with mock.patch.dict("os.environ", {}, clear=True):
            with self.assertRaises(ValueError):
                openai_client.send_request("Hi", "gpt-4o", base_url="http://127.0.0.1:%d/v1" % self.port)

    def test_http_error_propagates(self):
        with self.assertRaises(urllib.error.HTTPError) as ctx:
            openai_client.send_request(
                "Hi", "gpt-4o", api_key="wrong", base_url="http://127.0.0.1:%d/v1" % self.port
            )
        self.assertEqual(ctx.exception.code, 401)


if __name__ == "__main__":
    unittest.main(verbosity=2)
